#include <bits/stdc++.h>
using namespace std;

// Mo's algorithm for offline range queries.
// Complexity: O((n + q) * sqrt(n) * f) where f is the cost of add/remove.

struct Query {
    int l, r, idx;
};

int block_size;

bool cmp(const Query &a, const Query &b) {
    // Sort by block of l, then by r (zigzag within even blocks for cache locality).
    int block_a = a.l / block_size, block_b = b.l / block_size;
    if (block_a != block_b) return block_a < block_b;
    return (block_a & 1) ? (a.r > b.r) : (a.r < b.r);
}

// Example: count of distinct elements in [l, r].
// Adapt add/remove/get_answer for other queries (mode, sum with duplicates, etc.).
vector<long long> mo_s(vector<int> &a, vector<Query> &queries) {
    int n = (int)a.size();
    int q = (int)queries.size();

    // Coordinate compression (handles large values and negatives).
    vector<int> sorted_a = a;
    sort(sorted_a.begin(), sorted_a.end());
    sorted_a.erase(unique(sorted_a.begin(), sorted_a.end()), sorted_a.end());
    for (int &x : a)
        x = (int)(lower_bound(sorted_a.begin(), sorted_a.end(), x) - sorted_a.begin());
    int max_val = (int)sorted_a.size();

    // Block size: sqrt(n) is standard. Use n/sqrt(q) when q >> n for better complexity.
    block_size = max(1, (int)sqrt(n));
    sort(queries.begin(), queries.end(), cmp);

    vector<int> freq(max_val, 0);
    vector<long long> answers(q);
    long long cur_answer = 0;
    int cur_l = 0, cur_r = -1; // Current range is empty: [0, -1]

    // Add element at position pos to the current range.
    auto add = [&](int pos) {
        int val = a[pos];
        if (freq[val] == 0) cur_answer++;
        freq[val]++;
    };

    // Remove element at position pos from the current range.
    auto remove = [&](int pos) {
        int val = a[pos];
        freq[val]--;
        if (freq[val] == 0) cur_answer--;
    };

    for (const auto &qr : queries) {
        int l = qr.l, r = qr.r;

        // Expand/shrink to [l, r].
        while (cur_l > l) add(--cur_l);
        while (cur_r < r) add(++cur_r);
        while (cur_l < l) remove(cur_l++);
        while (cur_r > r) remove(cur_r--);

        answers[qr.idx] = cur_answer;
    }

    return answers;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, q;
    cin >> n >> q;

    vector<int> a(n);
    for (int &x : a) cin >> x;

    vector<Query> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].l >> queries[i].r;
        queries[i].l--; // Convert to 0-indexed.
        queries[i].r--;
        queries[i].idx = i;
    }

    auto answers = mo_s(a, queries);
    for (long long ans : answers)
        cout << ans << '\n';

    return 0;
}
